<?php declare(strict_types=1);require_once __DIR__.'/../config/config.php';require_once __DIR__.'/../config/database.php';require_once __DIR__.'/includes/auth.php';$db=db();$e=fn($v)=>htmlspecialchars((string)($v??''),ENT_QUOTES,'UTF-8');$id=(int)($_GET['invoice_id']??$_POST['invoice_id']??0);$s=$db->prepare('SELECT * FROM invoices WHERE id=? LIMIT 1');$s->execute([$id]);$i=$s->fetch();if(!$i){http_response_code(404);exit('Invoice not found.');}if($_SERVER['REQUEST_METHOD']==='POST'){$amount=(float)$_POST['amount'];$method=preg_replace('/[^A-Za-z0-9 _-]/','',(string)$_POST['gateway']);$ref='MAN-'.date('YmdHis').'-'.bin2hex(random_bytes(3));if($amount<=0||$amount>(float)$i['balance_due'])exit('Invalid payment amount.');$db->beginTransaction();try{$db->prepare("INSERT INTO invoice_payments (invoice_id,lead_id,reference,gateway,amount,currency,status,paid_at,metadata) VALUES (?,?,?,?,?,?, 'successful',NOW(),?)")->execute([$i['id'],$i['lead_id'],$ref,$method,$amount,$i['currency'],json_encode(['manual'=>true])]);$paid=(float)$i['amount_paid']+$amount;$balance=max(0,(float)$i['total']-$paid);$status=$balance<=0?'paid':'partially_paid';$db->prepare('UPDATE invoices SET amount_paid=?,balance_due=?,status=? WHERE id=?')->execute([$paid,$balance,$status,$i['id']]);$db->prepare('INSERT INTO invoice_events (invoice_id,event_type,description) VALUES (?,?,?)')->execute([$i['id'],'manual_payment','Manual payment '.$ref.' recorded.']);$db->prepare('INSERT INTO lead_activities (lead_id,activity_type,subject,description) VALUES (?,?,?,?)')->execute([$i['lead_id'],'payment','Manual payment received','Reference '.$ref]);$db->commit();header('Location: payment-receipt.php?reference='.urlencode($ref));exit;}catch(Throwable $x){$db->rollBack();exit('Unable to record payment.');}}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Manual Payment</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><main class="container py-5" style="max-width:650px"><div class="card"><div class="card-body"><h1 class="h3">Record Manual Payment</h1><p>Invoice <?=$e($i['invoice_number'])?> — Balance <?=$e($i['currency'])?> <?=number_format((float)$i['balance_due'],2)?></p><form method="post"><input type="hidden" name="invoice_id" value="<?=$i['id']?>"><label class="form-label">Amount</label><input class="form-control mb-3" name="amount" type="number" step="0.01" max="<?=e($i['balance_due'])?>" required><label class="form-label">Payment Method</label><select class="form-select mb-3" name="gateway"><option>bank_transfer</option><option>cash</option><option>card_manual</option><option>other</option></select><button class="btn btn-dark">Record Payment</button></form></div></div></main></body></html>